html:input.style:
flex: 0 0 auto;
width: 200px;
padding: 0.15em 0.1em 4px 0.1em;
border: none;
border-bottom: 1px solid rgba(0, 0, 0, 0.4);
border-radius: 0;
background-color: transparent;
font: inherit;
line-height: inherit;

